import hashlib, json, unicodedata, re
def nfcws1(s): return re.sub(r'\s+',' ',unicodedata.normalize('NFC',s)).strip()
def sha(s): return 'sha256:'+hashlib.sha256(s.encode('utf-8')).hexdigest()
def cy(s): return "'" + s.replace('\\','\\\\').replace("'","\\'").replace('\n','\\n') + "'"
def seghash(cfg): return sha(json.dumps(cfg, sort_keys=True, separators=(',',':')))
def chunks(text, size, overlap):
    out=[]; i=0; step=size-overlap; idx=0
    while i < len(text):
        out.append((idx, i, min(i+size, len(text)), text[i:i+size])); idx+=1
        if i+size >= len(text): break
        i += step
    return out
