def overlapping(C, s, e): return [c for c in C if c[1] < e and s < c[2]]
P['G1_overlap']=[(c[0],c[1],c[2], c[1]<=s1 and e1<=c[2]) for c in overlapping(C1,s1,e1)]
P['G2_overlap']=[(c[0],c[1],c[2], c[1]<=s1 and e1<=c[2]) for c in overlapping(C2,s1,e1)]
P['G3_overlap']=[(c[0],c[1],c[2], c[1]<=s2 and e2<=c[2]) for c in overlapping(C3,s2,e2)]
P['nC1']=len(C1); P['nC2']=len(C2); P['nC3']=len(C3)
json.dump(P, open('gen01-params.json','w'), indent=1)
