w(";\nMATCH (d:Document {uid: 'hu:document:w20f01-transcript-page'}), (act:Activity {uid: 'hu:activity:w20f01-capture-1'})\nMERGE (s:SourceSnapshot:InformationArtifact {uid: 'hu:snapshot:w20f01-page-2026-10-03'})\nSET s.artifactType = 'SourceSnapshot', s.canonicalUri = d.canonicalUri, s.retrievedAt = datetime('2026-10-03T00:00:00Z'), s.observedAt = datetime('2026-10-03T00:00:00Z'),\n    s.contentHash = 'sha256:679755704dd94340c363a46c4b5cb726e6a3843253fd7ae5cdabb0aa04b18834', s.contentHashBasis = 'SYNTHETIC_FIXTURE', s.captureCompleteness = 'COMPLETE',\n    s.publisherRevisionNotice = 'This transcript is under review (synthetic).', s.mimeType = 'text/html', s.language = 'en', s.createdAt = datetime('2026-10-03T00:00:00Z')\nMERGE (d)-[:HAS_SNAPSHOT]->(s)\nMERGE (s)-[:WAS_GENERATED_BY]->(act)")
w(f";\nMATCH (d:Document {{uid: 'hu:document:w20f01-transcript-page'}}), (s:SourceSnapshot {{uid: 'hu:snapshot:w20f01-page-2026-10-03'}}), (act:Activity {{uid: 'hu:activity:w20f01-extract-1'}})\nMERGE (tv:DocumentTextVersion:InformationArtifact {{uid: 'hu:text-version:w20f01-tv1'}})\nSET tv.documentTextVersionId = 'w20f01-tv1', tv.artifactType = 'DocumentTextVersion', tv.versionLabel = 'html-text-extract-v2',\n    tv.text = {cy(T1)},\n    tv.textVersionHash = '{P['T1hash']}', tv.contentHash = '{P['T1hash']}', tv.source = 'html-text-extract', tv.normalizationVersion = NULL, tv.languageCode = 'en',\n    tv.observedAt = s.observedAt, tv.createdAt = datetime('2026-10-03T00:05:00Z'), tv.updatedAt = datetime('2026-10-03T00:05:00Z')\nMERGE (d)-[:HAS_TEXT_VERSION]->(tv)\nMERGE (tv)-[:TEXT_OF_SNAPSHOT]->(s)\nMERGE (tv)-[:WAS_GENERATED_BY]->(act)")
