w(";\nMATCH (l:SourceLocator {uid: 'hu:locator:w20f01-l1-nmn-gram'}), (sub:ChemicalSubstance {uid: 'hu:substance:w20f01-nmn'}), (act:Activity {uid: 'hu:activity:w20f01-extract-1'})\nMERGE (a:Assertion {uid: 'hu:assertion:w20f01-a1-nmn-gram-daily'})\nSET a.predicate = 'SELF_REPORTED_DAILY_INTAKE', a.status = 'ACCEPTED', a.recordedAt = datetime('2026-10-03T01:00:00Z'), a.valueNumber = 1.0, a.unitCode = 'g',\n    a.quantityBasis = 'PER_DAY', a.polarity = 'POSITIVE', a.assertionBasis = 'PERSONAL_EXPERIENCE', a.speechAct = 'REPORTS_PRACTICE',\n    a.contentHash = 'sha256:fb8ed2f17fcbc00ecaaf7e08473f0395639b128b418290310818dc1e5e33cf99', a.createdAt = datetime('2026-10-03T01:00:00Z')\nMERGE (a)-[:HAS_SUBJECT]->(sub)\nMERGE (a)-[:SUPPORTED_BY]->(l)\nMERGE (a)-[:WAS_GENERATED_BY]->(act)")
w(";\nMATCH (a:Assertion {uid: 'hu:assertion:w20f01-a1-nmn-gram-daily'})\nMERGE (j:Adjudication:EvidenceAssessment {uid: 'hu:adjudication:w20f01-cf-a1'})\nSET j.assessmentType = 'Adjudication', j.adjudicationKind = 'CAPTURE_FIDELITY', j.verdict = 'SUPPORTED', j.reviewerType = 'HUMAN', j.methodVersion = 'w20-fixture-review-v1',\n    j.status = 'ACCEPTED', j.reviewedAt = datetime('2026-10-03T02:00:00Z'), j.recordedAt = datetime('2026-10-03T02:00:00Z'), j.createdAt = datetime('2026-10-03T02:00:00Z')\nMERGE (j)-[:EVALUATES]->(a)")
w(";\n// derived document-level shortcut (live SUPPORTED_BY_DOCUMENT) naming its locator\nMATCH (a:Assertion {uid: 'hu:assertion:w20f01-a1-nmn-gram-daily'}), (d:Document {uid: 'hu:document:w20f01-transcript-page'})\nMERGE (a)-[r:SUPPORTED_BY_DOCUMENT]->(d)\nSET r.derivationRule = 'support-via-locator-document-v1', r.derivedFromAssertionUids = ['hu:assertion:w20f01-a1-nmn-gram-daily'], r.locatorUid = 'hu:locator:w20f01-l1-nmn-gram', r.derivedAt = datetime('2026-10-03T03:00:00Z')")
def seg_block(guid, gid, tvuid, cfg, h, C, act, at, docuid):
    out=[]
    out.append(f";\n// segmentation {guid}: config {json.dumps(cfg, sort_keys=True)}\nMATCH (tv:DocumentTextVersion {{uid: '{tvuid}'}}), (act:Activity {{uid: '{act}'}})\nMERGE (g:Segmentation:InformationArtifact {{uid: '{guid}'}})\nSET g.segmentationId = '{gid}', g.artifactType = 'Segmentation', g.segmentationHash = '{h}', g.chunkSize = {cfg['chunkSize']}, g.overlap = {cfg['overlap']},\n    g.strategy = '{cfg['strategy']}', g.methodVersion = '{cfg['methodVersion']}', g.createdAt = datetime('{at}'), g.updatedAt = datetime('{at}')\nMERGE (tv)-[:HAS_SEGMENTATION]->(g)\nMERGE (g)-[:WAS_GENERATED_BY]->(act)")
    for (idx,cs,ce,txt) in C:
        cuid = f"hu:chunk:{gid}-c{idx}"
        out.append(f";\nMATCH (tv:DocumentTextVersion {{uid: '{tvuid}'}}), (d:Document {{uid: '{docuid}'}})\nMERGE (c:Chunk:InformationArtifact {{uid: '{cuid}'}})\nSET c.chunkId = '{gid}-c{idx}', c.chunkKey = '{gid}#{idx}', c.artifactType = 'Chunk', c.index = {idx}, c.text = {cy(txt)}, c.segmentationHash = '{h}',\n    c.charStart = {cs}, c.charEnd = {ce}, c.contentHash = '{sha(txt)}', c.createdAt = datetime('{at}'), c.updatedAt = datetime('{at}')\nMERGE (c)-[:FROM_TEXT_VERSION]->(tv)\nMERGE (d)-[hc:HAS_CHUNK]->(c) SET hc.derivationRule = 'chunk-of-document-text-version-v1', hc.derivedAt = datetime('{at}')")
    for k in range(len(C)-1):
        out.append(f";\nMATCH (a:Chunk {{uid: 'hu:chunk:{gid}-c{k}'}}), (b:Chunk {{uid: 'hu:chunk:{gid}-c{k+1}'}}) MERGE (a)-[:NEXT_CHUNK]->(b)")
    return out
def resolve_block(luid, gid, overlaps, h, at, auid=None, act=None):
    out=[]
    for (idx,cs,ce,whole) in overlaps:
        out.append(f";\nMATCH (l:SourceLocator {{uid: '{luid}'}}), (c:Chunk {{uid: 'hu:chunk:{gid}-c{idx}'}})\nMERGE (l)-[r:RESOLVES_TO_CHUNK]->(c)\nSET r.derivationRule = 'offset-overlap-v1', r.segmentationHash = '{h}', r.coversWholeSpan = {str(whole).lower()}, r.derivedAt = datetime('{at}'), r.activityUid = '{act}'")
        if auid:
            out.append(f";\nMATCH (a:Assertion {{uid: '{auid}'}}), (c:Chunk {{uid: 'hu:chunk:{gid}-c{idx}'}})\nMERGE (a)-[r:SUPPORTED_BY_CHUNK]->(c)\nSET r.derivationRule = 'support-via-locator-chunk-v1', r.derivedFromAssertionUids = ['{auid}'], r.locatorUid = '{luid}', r.segmentationHash = '{h}', r.derivedAt = datetime('{at}'), r.activityUid = '{act}'")
    return out
