w(f";\nMATCH (d:Document {{uid: 'hu:document:w20f01-transcript-page'}}), (s:SourceSnapshot {{uid: 'hu:snapshot:w20f01-page-2026-11-02'}}), (act:Activity {{uid: 'hu:activity:w20f01-extract-2'}})\nMERGE (tv:DocumentTextVersion:InformationArtifact {{uid: 'hu:text-version:w20f01-tv2'}})\nSET tv.documentTextVersionId = 'w20f01-tv2', tv.artifactType = 'DocumentTextVersion', tv.versionLabel = 'html-text-extract-v2',\n    tv.text = {cy(T2)},\n    tv.textVersionHash = '{P['T2hash']}', tv.contentHash = '{P['T2hash']}', tv.source = 'html-text-extract', tv.languageCode = 'en',\n    tv.observedAt = s.observedAt, tv.createdAt = datetime('2026-11-02T00:05:00Z'), tv.updatedAt = datetime('2026-11-02T00:05:00Z')\nMERGE (d)-[:HAS_TEXT_VERSION]->(tv)\nMERGE (tv)-[:TEXT_OF_SNAPSHOT]->(s)\nMERGE (tv)-[:WAS_GENERATED_BY]->(act)")
